'use strict';
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),zlib=require('node:zlib');
const {normalizeDocument}=require('./document');
const {GlobalFonts}=require('@napi-rs/canvas');
const digest=b=>crypto.createHash('sha256').update(b).digest('hex');
function fail(code,message){throw Object.assign(new Error(message),{code});}
const MAX=32*1024*1024,MAX_ARCHIVE=256*1024*1024,MAX_FILES=8192; // per-entry / whole archive / entries (pixel layers add many tiles)
const table=Uint32Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0;});
function crc32(b){let c=0xffffffff;for(const x of b)c=table[(c^x)&255]^(c>>>8);return (c^0xffffffff)>>>0;}
function safeName(name){if(typeof name!=='string'||name.length>180||!name||name.includes('\\')||name.startsWith('/')||name.split('/').some(p=>!p||p==='.'||p==='..')||/[:\0]/.test(name))fail('INVALID_BUNDLE','Unsafe archive entry');return name;}
function zip(entries){let offset=0;const locals=[],central=[];for(const [name,bytes] of entries){safeName(name);const n=Buffer.from(name),crc=crc32(bytes),head=Buffer.alloc(30);head.writeUInt32LE(0x04034b50);head.writeUInt16LE(20,4);head.writeUInt16LE(0x800,6);head.writeUInt32LE(crc,14);head.writeUInt32LE(bytes.length,18);head.writeUInt32LE(bytes.length,22);head.writeUInt16LE(n.length,26);locals.push(head,n,bytes);const c=Buffer.alloc(46);c.writeUInt32LE(0x02014b50);c.writeUInt16LE(20,4);c.writeUInt16LE(20,6);c.writeUInt16LE(0x800,8);c.writeUInt32LE(crc,16);c.writeUInt32LE(bytes.length,20);c.writeUInt32LE(bytes.length,24);c.writeUInt16LE(n.length,28);c.writeUInt32LE(offset,42);central.push(c,n);offset+=head.length+n.length+bytes.length;}const end=Buffer.alloc(22),cent=Buffer.concat(central);end.writeUInt32LE(0x06054b50);end.writeUInt16LE(entries.length,8);end.writeUInt16LE(entries.length,10);end.writeUInt32LE(cent.length,12);end.writeUInt32LE(offset,16);return Buffer.concat([...locals,cent,end]);}
function unzip(bytes){if(!Buffer.isBuffer(bytes)||bytes.length>MAX_ARCHIVE||bytes.length<22)fail('INVALID_BUNDLE','Invalid archive size');const result=new Map();let at=0,total=0;while(at+4<=bytes.length&&bytes.readUInt32LE(at)===0x04034b50){if(at+30>bytes.length)fail('INVALID_BUNDLE','Truncated archive');const flags=bytes.readUInt16LE(at+6),method=bytes.readUInt16LE(at+8),crc=bytes.readUInt32LE(at+14),packed=bytes.readUInt32LE(at+18),size=bytes.readUInt32LE(at+22),names=bytes.readUInt16LE(at+26),extra=bytes.readUInt16LE(at+28);if(flags&9||![0,8].includes(method)||size>MAX||packed>MAX)fail('INVALID_BUNDLE','Unsupported archive entry');const end=at+30+names+extra+packed;if(end>bytes.length)fail('INVALID_BUNDLE','Truncated archive');const name=safeName(bytes.subarray(at+30,at+30+names).toString('utf8'));if(result.has(name)||result.size>=MAX_FILES)fail('INVALID_BUNDLE','Duplicate or excessive entries');const raw=bytes.subarray(at+30+names+extra,end),data=method===0?Buffer.from(raw):zlib.inflateRawSync(raw,{maxOutputLength:MAX});total+=data.length;if(data.length!==size||crc32(data)!==crc||total>MAX)fail('INVALID_BUNDLE','Entry integrity or size mismatch');result.set(name,data);at=end;}if(!result.size||at+4>bytes.length||bytes.readUInt32LE(at)!==0x02014b50)fail('INVALID_BUNDLE','Archive central directory is missing');const start=at,seen=new Set();while(at+46<=bytes.length&&bytes.readUInt32LE(at)===0x02014b50){const n=bytes.readUInt16LE(at+28),x=bytes.readUInt16LE(at+30),c=bytes.readUInt16LE(at+32),end=at+46+n+x+c;if(end>bytes.length)fail('INVALID_BUNDLE','Truncated central directory');const name=safeName(bytes.subarray(at+46,at+46+n).toString('utf8'));if(seen.has(name)||!result.has(name)||bytes.readUInt32LE(at+24)!==result.get(name).length||bytes.readUInt32LE(at+16)!==crc32(result.get(name)))fail('INVALID_BUNDLE','Central directory integrity mismatch');seen.add(name);at=end;}if(seen.size!==result.size||at+22!==bytes.length||bytes.readUInt32LE(at)!==0x06054b50||bytes.readUInt16LE(at+4)!==0||bytes.readUInt16LE(at+6)!==0||bytes.readUInt16LE(at+8)!==seen.size||bytes.readUInt16LE(at+10)!==seen.size||bytes.readUInt32LE(at+12)!==at-start||bytes.readUInt32LE(at+16)!==start||bytes.readUInt16LE(at+20)!==0)fail('INVALID_BUNDLE','Invalid archive directory or trailer');return result;}
function exportBundle(doc,ctx){const entries=[],records=[],add=(name,bytes,extra={})=>{if(bytes.length>MAX)fail('BUNDLE_TOO_LARGE','Bundle entry exceeds limit');entries.push([name,bytes]);records.push({name,bytes:bytes.length,sha256:digest(bytes),...extra});};add('scene.json',Buffer.from(JSON.stringify(doc)),{kind:'scene'});const materialRecords=require('./material-assets').getMaterialAssets(ctx).exportRecords(doc);const ids=new Set(materialRecords.map(r=>r.assetId)),fonts=new Set();for(const layer of doc.layers)for(const o of layer.objects){if(o.assetId)ids.add(o.assetId);if(o.type==='text')fonts.add(o.font.family+'-'+(o.font.weight>=600?'Bold':'Regular')+'.ttf');}
// Pixel layer tiles: content-addressed PNGs (name = sha256 of the bytes).
const tileStore=require('./raster').tileStore(ctx),tileHashes=new Set();for(const layer of doc.layers)if(layer.raster)for(const h of Object.values(layer.raster.tiles))tileHashes.add(h);for(const h of tileHashes){const b=fs.readFileSync(tileStore.pathOf(h));if(digest(b)!==h)fail('ASSET_INTEGRITY','Pixel tile content differs from its hash');add('tiles/'+h+'.png',b,{kind:'tile',hash:h})}
for(const id of ids){const a=ctx.assets.get(id),file=ctx.assets.pathOf(id),b=fs.readFileSync(file);if(digest(b)!==a.sha256)fail('ASSET_INTEGRITY','Asset content differs from its registered hash');add('assets/'+a.file,b,{kind:'asset',asset:{...a}});}
for(const name of fonts){const fontFile=fs.existsSync(path.join(ctx.fontsDir,name))?path.join(ctx.fontsDir,name):path.join(ctx.assetsDir,'bundle-fonts',name);if(!/^[a-zA-Z]+-(Regular|Bold)\.ttf$/.test(name)||!fs.existsSync(fontFile))fail('BUNDLE_FONT_UNAVAILABLE','Self-contained bundles require a bundled font');add('fonts/'+name,fs.readFileSync(fontFile),{kind:'font',family:name.split('-')[0]});}
const licenses=fs.existsSync(path.join(ctx.fontsDir,'licenses'))?path.join(ctx.fontsDir,'licenses'):path.join(ctx.assetsDir,'bundle-fonts','licenses');if(fonts.size&&fs.existsSync(licenses))for(const file of fs.readdirSync(licenses)){if(fs.statSync(path.join(licenses,file)).isFile())add('licenses/'+file,fs.readFileSync(path.join(licenses,file)),{kind:'license'});}
const manifest={schema:'artforge.project-bundle',version:1,documentId:doc.id,entries:records,materials:materialRecords,provenance:{generator:'ArtForge',fontLicense:'bundled OFL license files',assetSources:'registered asset hash/metadata; no unrelated references'}};entries.unshift(['manifest.json',Buffer.from(JSON.stringify(manifest,null,2))]);const buffer=zip(entries);if(buffer.length>MAX)fail('BUNDLE_TOO_LARGE','Project exceeds32MiB');return {buffer,manifest};}
async function importBundle(buffer,ctx,options={}){const entries=unzip(buffer);if(!entries.has('manifest.json')||!entries.has('scene.json'))fail('INVALID_BUNDLE','Manifest and scene are required');let manifest,parsed;try{manifest=JSON.parse(entries.get('manifest.json'));parsed=JSON.parse(entries.get('scene.json'));}catch{fail('INVALID_BUNDLE','Invalid bundle JSON');}if(manifest.schema!=='artforge.project-bundle'||manifest.version!==1||!Array.isArray(manifest.entries))fail('INVALID_BUNDLE','Unsupported manifest');const allowed=new Set(['manifest.json']);for(const e of manifest.entries){safeName(e.name);if(allowed.has(e.name))fail('INVALID_BUNDLE','Duplicate manifest entry');allowed.add(e.name);const b=entries.get(e.name);if(!b||b.length!==e.bytes||digest(b)!==e.sha256)fail('BUNDLE_INTEGRITY','Missing/corrupt bundle entry');if(!['scene','asset','font','license','tile'].includes(e.kind))fail('INVALID_BUNDLE','Unknown entry kind')
if(e.kind==='tile'&&(!/^tiles\/[0-9a-f]{64}\.png$/.test(e.name)||e.name!=='tiles/'+e.hash+'.png'||e.sha256!==e.hash))fail('INVALID_BUNDLE','Invalid pixel tile entry');if(e.kind==='font'&&!/^fonts\/[A-Za-z]+-(Regular|Bold)\.ttf$/.test(e.name))fail('INVALID_BUNDLE','Invalid font entry');if(e.kind==='asset'&&(!e.asset||!/^asset_[a-zA-Z0-9_-]+$/.test(e.asset.id)||!/^assets\/asset_[a-zA-Z0-9_-]+\.(png|jpg|jpeg|webp)$/.test(e.name)))fail('INVALID_BUNDLE','Invalid asset entry');}
if(entries.size!==allowed.size||[...entries.keys()].some(n=>!allowed.has(n)))fail('INVALID_BUNDLE','Unlisted bundle entry');const doc=normalizeDocument(parsed);const assetEntries=new Map(manifest.entries.filter(e=>e.kind==='asset').map(e=>[e.asset.id,e]));for(const l of doc.layers)for(const o of l.objects)if(o.assetId&&!assetEntries.has(o.assetId))fail('BUNDLE_ASSET_MISSING','Referenced asset is absent')
const tileEntries=manifest.entries.filter(e=>e.kind==='tile'),tileSet=new Set(tileEntries.map(e=>e.hash))
for(const l of doc.layers)if(l.raster)for(const h of Object.values(l.raster.tiles))if(!tileSet.has(h))fail('BUNDLE_ASSET_MISSING','Referenced pixel tile is absent');for(const e of assetEntries.values()){const old=ctx.assets.index.assets[e.asset.id];if(old&&old.sha256!==e.sha256)fail('BUNDLE_ASSET_CONFLICT','Asset identifier conflicts with existing bytes');}
for(const e of assetEntries.values()){const b=entries.get(e.name);if(e.asset.sha256!==e.sha256||e.asset.bytes!==b.length||path.basename(e.name)!==e.asset.file)fail('BUNDLE_INTEGRITY','Asset manifest mismatch');let image;try{image=await require('@napi-rs/canvas').loadImage(b);}catch{fail('INVALID_BUNDLE','Image bytes are invalid');}if(image.width*image.height>16777216)fail('INVALID_BUNDLE','Image dimensions exceed bundle decode limit');}for(const e of manifest.entries.filter(e=>e.kind==='font')){const magic=entries.get(e.name).subarray(0,4).toString('hex');if(!['00010000','4f54544f','74727565'].includes(magic)||e.family!==path.basename(e.name).split('-')[0])fail('INVALID_BUNDLE','Invalid font payload');}
// All structure/hash/conflict checks precede writes. Staging bytes are contained,
// then registered through the existing authoritative stores (no second store).
const materials=manifest.materials||[];if(!Array.isArray(materials)||materials.length>100)fail('INVALID_BUNDLE','Invalid material metadata');for(const r of materials){if(!r||r.id!=='mat-img-'+r.sha256||!r.active||!assetEntries.has(r.assetId)||assetEntries.get(r.assetId).sha256!==r.sha256||!['wood','fabric','stone','paper','wall','metal','glass','leather'].includes(r.kind)||!r.source||!['owned','user-provided','licensed','public-domain'].includes(r.source.permission)||typeof r.source.sourceUri!=='string'||!r.source.sourceUri.trim())fail('INVALID_BUNDLE','Invalid material metadata');}for(const l of doc.layers)for(const o of l.objects)if(o.fill?.imageId&&!materials.some(r=>r.id===o.fill.imageId))fail('INVALID_BUNDLE','Missing material registration');
const files=new Map(),snapshot=file=>{if(!files.has(file))files.set(file,fs.existsSync(file)?fs.readFileSync(file):null);};const fontKeys=[];const oldIndex=JSON.parse(JSON.stringify(ctx.assets.index)),oldDocs=new Map(ctx.store.documents),oldRevisions=new Map(ctx.store.revisions),oldHistory=new Map(ctx.store.history),staged=path.join(ctx.assetsDir,'bundle-fonts');snapshot(ctx.assets.indexPath);snapshot(path.join(ctx.assetsDir,'material-index.json'));let opened;
try{require('./operation-context').checkpoint();fs.mkdirSync(staged,{recursive:true});for(const e of manifest.entries.filter(e=>e.kind==='font'||e.kind==='license')){const file=e.kind==='font'?path.join(staged,path.basename(e.name)):path.join(staged,'licenses',path.basename(e.name));snapshot(file);if(e.kind==='font'&&fs.existsSync(file)&&digest(fs.readFileSync(file))!==e.sha256)fail('BUNDLE_FONT_CONFLICT','Imported font conflicts with registered bytes');fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,entries.get(e.name));if(e.kind==='font'){const key=GlobalFonts.register(entries.get(e.name),e.family);if(!key)fail('INVALID_BUNDLE','Font payload cannot be decoded');fontKeys.push(key);}}
for(const e of assetEntries.values())if(!ctx.assets.index.assets[e.asset.id]){snapshot(path.join(ctx.assetsDir,e.asset.file));ctx.assets.registerBuffer(entries.get(e.name),path.extname(e.name),{id:e.asset.id,name:e.asset.name});}for(const e of tileEntries){const store=require('./raster').tileStore(ctx);snapshot(store.pathOf(e.hash));store.put(entries.get(e.name))}
require('./material-assets').getMaterialAssets(ctx).importRecords(materials);require('./operation-context').checkpoint();opened=ctx.store.openDocument(doc,{replace:options.replace===true});snapshot(ctx.store.fileFor(opened.document.id));ctx.store.save(opened.document.id);return {documentId:opened.document.id,manifest,document:opened.document};}catch(error){for(const key of fontKeys)GlobalFonts.remove(key);for(const [file,bytes] of [...files].reverse()){if(bytes===null){if(fs.existsSync(file))fs.unlinkSync(file);}else fs.writeFileSync(file,bytes);}ctx.assets.index=oldIndex;ctx.assets.imageCache.clear();ctx.store.documents=oldDocs;ctx.store.revisions=oldRevisions;ctx.store.history=oldHistory;throw error;}}

module.exports={exportBundle,importBundle,zip,unzip};
